#[test]
fn pillow_box_bytes_match_independent_reference_and_crop_windows() {
    for case in BYTE_CASES {
        let [width, height, output_width, output_height] = case.dimensions;
        let source = ImageSize::new(height, width).expect("positive reference source dimensions");
        let target = ImageSize::new(output_height, output_width)
            .expect("positive reference target dimensions");
        let actual = resize_u8(
            case.source,
            source,
            case.channels,
            target,
            ResizeFilter::Box,
            ResizeProfile::Pillow,
        )
        .expect("Pillow BOX byte resize");
        assert_eq!(
            actual, case.expected,
            "dimensions {:?}, channels {}",
            case.dimensions, case.channels
        );
        let pixel = ImageSize::new(1, 1).expect("single output pixel");
        let crop = ResizeCrop::new(target, output_width - 1, output_height - 1, pixel)
            .expect("bottom-right output crop");
        let cropped = resize_u8_crop(
            case.source,
            source,
            case.channels,
            crop,
            ResizeFilter::Box,
            ResizeProfile::Pillow,
        )
        .expect("Pillow BOX cropped resize");
        assert_eq!(
            cropped,
            &case.expected[case.expected.len() - case.channels..],
            "cropped dimensions {:?}",
            case.dimensions
        );
    }
}

#[test]
fn pillow_box_mode_f_matches_independent_float32_bits() {
    for case in FLOAT_CASES {
        let [width, height, output_width, output_height] = case.dimensions;
        let source = ImageSize::new(height, width).expect("positive reference source dimensions");
        let target = ImageSize::new(output_height, output_width)
            .expect("positive reference target dimensions");
        let values: Vec<f32> = case.source.iter().copied().map(f32::from_bits).collect();
        let actual = resize_f32(
            &values,
            source,
            case.channels,
            target,
            ResizeFilter::Box,
            ResizeProfile::Pillow,
        )
        .expect("Pillow BOX mode-F resize");
        let bits: Vec<u32> = actual.into_iter().map(f32::to_bits).collect();
        assert_eq!(bits, case.expected, "dimensions {:?}", case.dimensions);
    }
}
